package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonIntegerFormatVisitor;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonNumberFormatVisitor;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class LongSerializer_serialize_TriageGen0Test {

    private NumberSerializers.LongSerializer serializer;
    private JsonGenerator gen;
    private SerializerProvider provider;

    @Before
    public void setUp() {
        serializer = new NumberSerializers.LongSerializer();
        gen = Mockito.mock(JsonGenerator.class);
        provider = Mockito.mock(SerializerProvider.class);
    }

    @Test
    public void testSerialize_withValidLong() throws IOException {
        // Arrange
        Long value = 12345L;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert
        verify(gen).writeNumber(12345L);
    }

    @Test
    public void testSerialize_withZero() throws IOException {
        // Arrange
        Long value = 0L;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert
        verify(gen).writeNumber(0L);
    }

    @Test
    public void testSerialize_withNegativeLong() throws IOException {
        // Arrange
        Long value = -98765L;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert
        verify(gen).writeNumber(-98765L);
    }

    @Test(expected = ClassCastException.class)
    public void testSerialize_withInvalidType_ThrowsClassCastException() throws IOException {
        // Arrange
        String value = "not a long";

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected exception
    }

    @Test(expected = NullPointerException.class)
    public void testSerialize_withNull_ThrowsNullPointerException() throws IOException {
        // Arrange
        Object value = null;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected exception
    }

    @Test(expected = IOException.class)
    public void testSerialize_whenGeneratorThrowsIOException() throws IOException {
        // Arrange
        Long value = 100L;
        when(gen.writeNumber(100L)).thenThrow(new IOException("Simulated IO error"));

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected exception
    }
}
